def calculate_total_transfer_amount(transfers: List[Tuple[int, str, str, float, str]], account: str) -> float:
    """Calculates the total amount of credit transferred from a specific account."""
    total_amount = 0.0
    for transfer_id, sender_account, receiver_account, amount, timestamp in transfers:
