def sieve_of_eratosthenes(n):
    prime = [True] * n
    prime[0] = prime[1] = False
    for i in range(2, int(n**0.5) + 1):
        if prime[i]:
            for j in range(i*i, n, i):
                prime[j] = False
    primes = [i for i in range(n) if prime[i]]
    return primes

