def intersection_with_min_count(list1, list2):
    counts1 = {}
    for x in list1:
        counts1[x] = counts1.get(x, 0) + 1
    counts2 = {}
    for x in list2:
        counts2[x] = counts2.get(x, 0) + 1

    intersection = []
    seen = set()
    for x in list1:
        if x in counts2 and x not in seen:
            intersection.append((x, min(counts1[x], counts2[x])))
            seen.add(x)
    return intersection

