from typing import List, Tuple

def is_strongly_connected(edges: List[Tuple[int, int]]) -> bool:
    """
    Determines if the directed graph is strongly connected.
    """
    if not edges:
        return True

    graph = {}
    vertices = set()
    for u, v in edges:
        if u not in graph:
            graph[u] = []
        graph[u].append(v)
        vertices.add(u)
        vertices.add(v)

    if not vertices:
        return True

    def dfs(start_node, visited):
        visited.add(start_node)
        if start_node in graph:
            for neighbor in graph[start_node]:
                if neighbor not in visited:
                    dfs(neighbor, visited)

    first_node = next(iter(vertices))
    visited = set()
    dfs(first_node, visited)

    if len(visited) != len(vertices):
        return False

    reversed_graph = {}
    for u, v in edges:
        if v not in reversed_graph:
            reversed_graph[v] = []
        reversed_graph[v].append(u)

    visited = set()
    dfs(first_node, visited)

    if len(visited) != len(vertices):
        return False

    return True
```

