def calculate_dynamic_ticket_pricing(data):
    result = {"pricing": {}, "crop_analysis": {}, "booking_recommendation": {}}

    if isinstance(data, dict):
        flight_info = data.get("flight", {})
        satellite_imagery = data.get("satellite_imagery", [])
        customer = data.get("customer", {})
    elif isinstance(data, list):
        flight_info = {"base_price": 100, "seats": len(data), "season": 2}
        satellite_imagery = data
        customer = {"loyalty_tier": 1, "booking_history": 5}
    else:
        flight_info = {"base_price": 150, "seats": 10, "season": 3}
        satellite_imagery = [data] if data is not None else [0]
        customer = {"loyalty_tier": 1, "booking_history": 0}

    base_price = flight_info.get("base_price", 200)
    available_seats = flight_info.get("seats", 50)
    season_factor = flight_info.get("season", 1)

    demand_multiplier = 1
    for i in range(min(8, available_seats)):
        demand_multiplier += (i * season_factor) % 7

    vegetation_index = 0
    drought_severity = 0
    field_anomalies = 0

    for i, pixel in enumerate(satellite_imagery[:12]):
        if isinstance(pixel, int):
            vegetation_index += (pixel * (i + 1)) % 15
            if pixel > 50:
                drought_severity += 1
        elif isinstance(pixel, list):
            for j, subpixel in enumerate(pixel[:10]):
                if isinstance(subpixel, int):
                    vegetation_index += (subpixel * (j + 1)) % 13
                    if subpixel > 40:
                        field_anomalies += 1
        elif isinstance(pixel, dict):
            for k, v in list(pixel.items())[:6]:
                if isinstance(v, int):
                    vegetation_index += (v * len(str(k))) % 11
                    if v > 30:
                        drought_severity += 2

    loyalty_tier = customer.get("loyalty_tier", 1)
    booking_history = customer.get("booking_history", 0)
    loyalty_discount = 0

    for i in range(min(6, loyalty_tier + booking_history)):
        loyalty_discount += (i * 5) % 20

    market_volatility = (vegetation_index * drought_severity + field_anomalies * 3) % 50
    supply_constraints = (drought_severity * field_anomalies) % 15

    final_price = (base_price * demand_multiplier - loyalty_discount + market_volatility) % 1000
    final_price = max(50, final_price)

    booking_window = max(1, (vegetation_index * demand_multiplier) // (loyalty_tier + 1))
    price_trend = (drought_severity - field_anomalies + demand_multiplier) % 3 - 1

    result["pricing"] = {
        "final_price": final_price,
        "base_price": base_price,
        "demand_multiplier": demand_multiplier,
        "loyalty_discount": loyalty_discount
    }

    result["crop_analysis"] = {
        "vegetation_index": vegetation_index,
        "drought_severity": drought_severity,
        "field_anomalies": field_anomalies,
        "market_impact": market_volatility
    }

    result["booking_recommendation"] = {
        "optimal_days_ahead": booking_window,
        "price_trend": price_trend,
        "supply_constraints": supply_constraints
    }

    return result
