def is_palindrome(s):
    left = 0
    right = len(s) - 1
    while left < right:
        while left < right and not is_alphanumeric(s[left]):
            left += 1
        while left < right and not is_alphanumeric(s[right]):
            right -= 1
        if left < right and to_ascii(s[left]) != to_ascii(s[right]):
            return False
        left += 1
        right -= 1
    return True

def is_alphanumeric(char):
    ascii_val = ord(char)
    return (48 <= ascii_val <= 57) or (65 <= ascii_val <= 90) or (97 <= ascii_val <= 122)

def to_ascii(char):
    ascii_val = ord(char)
    if 65 <= ascii_val <= 90:
