```python
def topoSort(V, adj):
    """
    Finds a topological sorting of a DAG.

    Args:
        V: The number of vertices in the graph.
        adj: The adjacency list representing the graph.

    Returns:
        A list containing the vertices in topological order.
    """

    in_degree = [0] * V
    for i in range(V):
        for neighbor in adj[i]:
            in_degree[neighbor] += 1

    queue = []
    for i in range(V):
        if in_degree[i] == 0:
            queue.append(i)

    result = []
    while queue:
        u = queue.pop(0)
        result.append(u)

        for neighbor in adj[u]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    if len(result) != V:
        return []  # Graph has a cycle

    return result
```

