        if (row, col, energy) in memo:
            return memo[(row, col, energy)]

        if row == m - 1 and col == n - 1:
            if energy >= 0:
                return 1
            else:
                return 0

        if row >= m or col >= n or grid[row][col] == 1 or energy < 0:
            return 0

        paths = count_paths(row + 1, col, energy - 1) + count_paths(row, col + 1, energy - 1)
