public class Luhn
{
    public static bool IsValid(string number)
    {
        int sum = 0;
        bool doubleOdd = false;

        for (int i = number.Length - 1; i >= 0; i--)
        {
            int digit = number[i] - '0';

            if (doubleOdd)
            {
                digit *= 2;
                if (digit > 9)
                {
                    digit -= 9;
                }
            }

            sum += digit;
            doubleOdd = !doubleOdd;
        }

        return (sum % 10) == 0;
