void segregateEvenOdd(std::vector<int>& arr, int n) {
    std::vector<int> even;
    std::vector<int> odd;

    for (int i = 0; i < n; ++i) {
        if (arr[i] % 2 == 0) {
            even.push_back(arr[i]);
        } else {
            odd.push_back(arr[i]);
        }
    }

    std::sort(even.begin(), even.end());
    std::sort(odd.begin(), odd.end());

    int even_idx = 0;
    int odd_idx = 0;

    for (int i = 0; i < n; ++i) {
        if (even_idx < even.size()) {
            arr[i] = even[even_idx++];
        } else {
            arr[i] = odd[odd_idx++];
        }
    }
}
