import requests

def get_url_status(urls):
    """
    Retrieves the HTTP status code for each URL in the input list.

    Args:
        urls: A list of URLs.

    Returns:
        A dictionary mapping URLs to status codes or error messages.
    """

    results = {}
    for url in urls:
        try:
            response = requests.get(url, timeout=5)
            results[url] = response.status_code
        except requests.exceptions.InvalidURL:
            results[url] = 'Invalid URL: Missing schema (http/https)'
        except requests.exceptions.ConnectionError:
            results[url] = 'Connection error: Could not connect to the URL'
        except requests.exceptions.Timeout:
            results[url] = 'Timeout: The request timed out'
        except requests.exceptions.RequestException as e:
            results[url] = f'An error occurred: {e}'
        except Exception as e:
            results[url] = f'Unexpected error: {e}'
    return results

if __name__ == "__main__":
