def num_islands(grid):
    if not grid:
        return 0

    m, n = len(grid), len(grid[0])
    num_islands = 0

    def dfs(row, col):
        if row < 0 or row >= m or col < 0 or col >= n or grid[row][col] == 0:
            return

        grid[row][col] = 0  # Mark as visited

        dfs(row + 1, col)
        dfs(row - 1, col)
        dfs(row, col + 1)
        dfs(row, col - 1)

    for i in range(m):
        for j in range(n):
            if grid[i][j] == 1:
                num_islands += 1
                dfs(i, j)

    return num_islands

