def calculate_fibonacci_and_factorial(n):
    def fibonacci(n):
        if n <= 1:
            return n
        else:
            a, b = 0, 1
            for _ in range(2, n + 1):
                a, b = b, a + b
            return b

    def factorial(n):
        if n == 0:
            return 1
        else:
            result = 1
            for i in range(1, n + 1):
                result *= i
            return result

    fib_number = fibonacci(n)
    factorial_of_fib = factorial(fib_number)
    return (fib_number, factorial_of_fib)
