def ceil_in_bst(arr, x):
    if not arr:
        return -1

    root = arr[0]
    bst = [root]
    for i in range(1, len(arr)):
        node = arr[i]
        curr = root
        while True:
            if node < curr:
                if len(bst) <= bst.index(curr) * 2 + 1:
                    bst.append(None)
                if bst[bst.index(curr) * 2 + 1] is None:
                    bst[bst.index(curr) * 2 + 1] = node
                    break
                else:
                    curr = bst[bst.index(curr) * 2 + 1]
            else:
                if len(bst) <= bst.index(curr) * 2 + 2:
                    bst.append(None)
                if bst[bst.index(curr) * 2 + 2] is None:
                    bst[bst.index(curr) * 2 + 2] = node
                    break
                else:
                    curr = bst[bst.index(curr) * 2 + 2]

    ceil = -1
    curr = root
    while curr is not None:
        if curr >= x:
            ceil = curr
            if curr > x:
                break
        if x < curr:
            if len(bst) > bst.index(curr) * 2 + 1 and bst[bst.index(curr) * 2 + 1] is not None:
                curr = bst[bst.index(curr) * 2 + 1]
            else:
                curr = None
        else:
            if len(bst) > bst.index(curr) * 2 + 2 and bst[bst.index(curr) * 2 + 2] is not None:
                curr = bst[bst.index(curr) * 2 + 2]
            else:
                curr = None
    return ceil


