def max_prime_divisor(n: int) -> int:
    if n < 2:
        return -1
    n = abs(n)
    largest_prime = 1
    i = 2
    while i * i <= n:
        while n % i == 0:
            largest_prime = i
            n //= i
        i += 1
    if n > 1:
        largest_prime = n
    return largest_prime
