def solveNQueens(n):
    def isSafe(board, row, col):
        for i in range(row):
            if board[i] == col or abs(board[i] - col) == row - i:
                return False
        return True

    def solveNQueensUtil(row, board, solutions):
        if row == n:
            solution = []
            for i in range(n):
                row_str = ""
                for j in range(n):
                    if board[i] == j:
                        row_str += "Q"
                    else:
                        row_str += "."
                solution.append(row_str)
            solutions.append(solution)
            return

        for col in range(n):
            if isSafe(board, row, col):
                board[row] = col
                solveNQueensUtil(row + 1, board, solutions)

    solutions = []
    board = [0] * n
    solveNQueensUtil(0, board, solutions)
    return solutions
