def prime_factors_count(n):
    try:
        n = int(n)
        if n <= 1:
            return "Invalid input. Please provide an integer."
        factors = {}
        d = 2
        while d * d <= n:
            while n % d == 0:
                if d in factors:
                    factors[d] += 1
                else:
                    factors[d] = 1
                n //= d
            d += 1
        if n > 1:
            factors[n] = 1
        return factors
    except:
        return 'Invalid input. Please provide an integer.'
