def tribonacci_modulo(n):
    if n == 0 or n == 1:
        return 0
    if n == 2:
        return 1

    trib = [0, 0, 1]
    for i in range(3, n + 1):
        next_trib = (trib[i - 1] + trib[i - 2] + trib[i - 3]) % 26
        trib.append(next_trib)
    return trib[n]
