            if all(isinstance(x, int) for x in element):
                product = 1
                for n in element[:8]:
                    product = (product * n) % 10000
                return {"items": items, "sum": sum(element), "product": product, "path_id": len(path)}
            return {"items": items, "count": len(element), "path_id": len(path)}
        elif isinstance(element, str):
            if len(element) <= 5:
                return element
            chars = {}
            for c in element[:30]:
                chars[c] = chars.get(c, 0) + 1
            common = sorted(chars.items(), key=lambda x: (-x[1], x[0]))[:3]
            word_count = len(element.split())
            unique_chars = len(set(element))
            return {"length": len(element), "prefix": element[:5], "suffix": element[-5:], 
                    "common": common, "words": word_count, "unique": unique_chars}
        elif isinstance(element, int):
            factors = [i for i in range(1, min(20, abs(element) + 1)) 
                     if element != 0 and abs(element) % i == 0][:3]
            digits = [int(d) for d in str(abs(element))]
            digit_sum = sum(digits)
            return {"value": element, "factors": factors, "digit_sum": digit_sum,
                    "transform": (element * (depth + 1) + len(path)) % 997}
        else:
            return str(element)

    result = process_element(input_data)

    def build_summary(data):
        if isinstance(data, dict):
            return {"type": "dict", "keys": list(data.keys())[:5], "size": len(data)}
        elif isinstance(data, list):
            return {"type": "list", "length": len(data), 
                    "types": list(set(type(i).__name__ for i in data[:5]))}
        elif isinstance(data, str):
            return {"type": "string", "length": len(data), "preview": data[:10]}
        elif isinstance(data, int):
            return {"type": "integer", "value": data, "digits": len(str(abs(data)))}
        else:
            return {"type": str(type(data).__name__)}

    def complexity_score(data):
        if isinstance(data, dict):
            return min(sum(complexity_score(v) for k, v in list(data.items())[:5]) + 10, 100)
        elif isinstance(data, list):
            return min(sum(complexity_score(v) for v in data[:5]) + 5, 100)
        elif isinstance(data, str):
            return min(len(data), 30)
        elif isinstance(data, int):
            return min(len(str(abs(data))), 10) * 2
        else:
            return 1

    return {
        "result": result,
        "summary": build_summary(input_data),
        "complexity": complexity_score(input_data)
    }
