    for item, quantity in order.items():
        price = get_price(item)
        discount = get_discount(item, quantity)
        item_price = get_sale(item, quantity, price, discount)
        total_price += item_price
        invoice += f"{item} {quantity} {price} {discount*100:.1f}% {item_price:.2f}\n"
    invoice += f"Total = {total_price:.2f}"
    return invoice

