    counts = {}
    for num in nums:
        counts[num] = counts.get(num, 0) + 1

    max_freq = 0
    most_freq_num = float('inf')

    for num, freq in counts.items():
        if freq > max_freq:
            max_freq = freq
            most_freq_num = num
        elif freq == max_freq and num < most_freq_num:
            most_freq_num = num

    print(most_freq_num)

