    posts.append(post)
    return post

def read_post(id):
    for post in posts:
        if post["id"] == id:
            return post
    return {}

def update_post(id, title, content, author):
    for post in posts:
        if post["id"] == id:
            post["title"] = title
            post["content"] = content
            post["author"] = author
            post["date"] = "2020-01-01T00:00:00"
            return post
    return {}

def delete_post(id):
    for i, post in enumerate(posts):
        if post["id"] == id:
            del posts[i]
            return {}
    return {}

def read_all_posts():
